// HubSpot -> Ziffr (spec 0043): two counts for the month that has just ended, taken from HubSpot's own totals: deals won and
// new contacts. Only the two numbers leave: no deal, no contact, no name, no amount. A figure whose Metric slug is left empty
// is not sent.
const SLUG = /^[a-z0-9][a-z0-9-]{0,99}$/;
const s = $('Settings').first().json;
const want = (name) => {
  const v = String(s[name] ?? '').trim();
  if (v === '') return '';
  if (!SLUG.test(v)) throw new Error('Settings: ' + name + ' is not a Metric slug (lower case letters, digits and hyphens), or leave it empty to skip that figure.');
  return v;
};
const slugs = { won: want('dealsWonMetric'), contacts: want('newContactsMetric') };
if (!slugs.won && !slugs.contacts) throw new Error('Settings: name at least one Metric to fill.');
const totalOf = (node) => {
  const t = $(node).first().json.total;
  if (typeof t !== 'number' || !Number.isFinite(t) || t < 0) throw new Error('HubSpot did not say how many (' + node + '): no figure was sent.');
  return t;
};
// The month that has just ended, by its first day.
const now = new Date();
const period = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1)).toISOString().slice(0, 10);
const items = [];
if (slugs.won) items.push({ metric: slugs.won, period, value: totalOf('Count deals won') });
if (slugs.contacts) items.push({ metric: slugs.contacts, period, value: totalOf('Count new contacts') });
// One run sends once, also when n8n retries it: the same figures give the same key, other figures another.
let h = 5381;
const body = JSON.stringify(items);
for (let i = 0; i < body.length; i++) h = ((h * 33) ^ body.charCodeAt(i)) >>> 0;
const key = 'hubspot-' + new Date().toISOString().slice(0, 10) + '-' + h.toString(36) + '-' + items.length;
return [{ json: { items, skipped: [], key } }];

// Ziffr's answer to a batch of values (spec 0043): one result per item, in the order sent. A refused item fails the run,
// so that n8n shows it as failed and its owner looks; the rest were recorded all the same (each item stands on its own).
const results = Array.isArray($input.first().json.results) ? $input.first().json.results : [];
const shaped = $('Shape values').first().json;
const refused = results.filter((r) => r.status === 'refused');
if (refused.length) {
  const why = refused.slice(0, 10).map((r) => String(r.metric) + ' ' + String(r.period ?? '') + ' (' + String(r.code ?? 'refused') + '): ' + String(r.detail)).join('; ');
  throw new Error('Ziffr refused ' + refused.length + ' of ' + results.length + ' values: ' + why + (refused.length > 10 ? '; and more' : ''));
}
const count = (s) => results.filter((r) => r.status === s).length;
return [{ json: { recorded: count('recorded'), waitingForApproval: count('awaiting_approval'), proposedAsCorrection: count('locked'), skippedRows: shaped.skipped } }];
